// Collision bodies deliberately stay outside each station's navigable docking area.
export const OBSTACLES=[{x:-39,z:1,r:10.7},{x:37,z:-19,r:8.8},{x:42,z:37,r:9.2},{x:-12,z:44,r:10.8},{x:-38,z:-40,r:9.7},{x:62,z:-47,r:7.8},{x:9,z:-47,r:4.5},{x:-57,z:27,r:4.7}];
export const distance=(a,b)=>Math.hypot(a.x-b.x,a.z-b.z);
export function angleDelta(a,b){return Math.atan2(Math.sin(b-a),Math.cos(b-a));}
export function constrain(p,obstacles=OBSTACLES,padding=1.4){let hit=false;for(const o of obstacles){let dx=p.x-o.x,dz=p.z-o.z,d=Math.hypot(dx,dz),r=o.r+padding;if(d<r){if(d<.001){dx=1;dz=0;d=1;}p.x=o.x+dx/d*r;p.z=o.z+dz/d*r;hit=true;}}const x=Math.max(-WORLD_LIMIT,Math.min(WORLD_LIMIT,p.x)),z=Math.max(-WORLD_LIMIT,Math.min(WORLD_LIMIT,p.z));if(x!==p.x||z!==p.z)hit=true;p.x=x;p.z=z;return hit;}
export function isClear(a,b,obstacles=OBSTACLES,padding=2.2){const dx=b.x-a.x,dz=b.z-a.z,l=dx*dx+dz*dz;for(const o of obstacles){let t=l?((o.x-a.x)*dx+(o.z-a.z)*dz)/l:0;t=Math.max(0,Math.min(1,t));if(Math.hypot(a.x+t*dx-o.x,a.z+t*dz-o.z)<o.r+padding)return false;}return true;}
// Visibility graph routing around obstacle perimeters, with Dijkstra shortest path.
export function planRoute(start,goal,obstacles=OBSTACLES){if(isClear(start,goal,obstacles))return [{...goal}];const nodes=[{x:start.x,z:start.z},{x:goal.x,z:goal.z}];for(const o of obstacles){for(let i=0;i<16;i++){const a=i*Math.PI/8,r=o.r+3.3,p={x:o.x+Math.cos(a)*r,z:o.z+Math.sin(a)*r};if(Math.abs(p.x)>75||Math.abs(p.z)>75)continue;if(obstacles.every(v=>distance(p,v)>v.r+2.4))nodes.push(p);}}
 const distances=Array(nodes.length).fill(Infinity),prev=Array(nodes.length).fill(-1),done=new Set();distances[0]=0;for(let n=0;n<nodes.length;n++){let u=-1;for(let i=0;i<nodes.length;i++)if(!done.has(i)&&(u<0||distances[i]<distances[u]))u=i;if(u<0||!Number.isFinite(distances[u]))break;if(u===1)break;done.add(u);for(let v=0;v<nodes.length;v++){if(done.has(v)||v===u||!isClear(nodes[u],nodes[v],obstacles))continue;const d=distances[u]+distance(nodes[u],nodes[v]);if(d<distances[v]){distances[v]=d;prev[v]=u;}}}
 if(!Number.isFinite(distances[1]))return [];const path=[];for(let u=1;u>0;u=prev[u]){if(u<0)return [];path.unshift(nodes[u]);}return path;}
export function stepBoat(state,input,dt,obstacles=OBSTACLES){dt=Math.min(.05,dt);const accel=input.throttle??0,turn=input.turn??0;state.heading+=turn*dt*1.9*(.3+Math.min(1,Math.abs(state.speed)/5));const max=input.boost?18:10;state.speed+=accel*12*dt;state.speed*=Math.exp(-(accel? .36:1.55)*dt);state.speed=Math.max(-4,Math.min(max,state.speed));state.x+=Math.sin(state.heading)*state.speed*dt;state.z+=Math.cos(state.heading)*state.speed*dt;const hit=constrain(state,obstacles);if(hit)state.speed*=.45;return hit;}
export function followRoute(state,route,dt){while(route.length&&distance(state,route[0])<1.3)route.shift();if(!route.length){state.speed*=Math.exp(-8*dt);return true;}const goal=route[0],a=Math.atan2(goal.x-state.x,goal.z-state.z),delta=angleDelta(state.heading,a);state.heading+=Math.max(-2.1*dt,Math.min(2.1*dt,delta));const desired=Math.max(.8,Math.min(6,distance(state,goal)*1.2))*(Math.abs(delta)>1?.2:1);state.speed+=(desired-state.speed)*Math.min(1,dt*4);state.x+=Math.sin(state.heading)*state.speed*dt;state.z+=Math.cos(state.heading)*state.speed*dt;constrain(state);return false;}
